// Isolated real browser; production typing presenter/Notebook and built-in markup.
const fs=require('fs'),path=require('path'),http=require('http'),assert=require('node:assert/strict');
const {chromium}=require(process.env.AGENTNET_PLAYWRIGHT||'playwright-core');
const base=path.resolve(__dirname,'../static'), notebook=path.resolve(__dirname,'../../../examples/skins/notebook');
const markup=fs.readFileSync(path.join(base,'default.html'),'utf8').replace(/<script\b[^>]*>[\s\S]*?<\/script>/g,'');
const bootstrap=`import {mountTyping} from '/assets/typing.mjs';
window.calls=[];window.prefs={send:true,show:true};window.entries=[];window.online=true;window.held=null;
window.provider=async(path,body)=>{calls.push({path,body});if(path==='/api/typing/preferences'){if(window.saveGate)await window.saveGate;prefs=body;return prefs;}if(body)return {submitted:1};if(held){const wait=held;held=null;await wait;}return {current:online,supported:true,preferences:prefs,entries};};
const input=document.querySelector('#body'),line=document.querySelector('#typing-line'),settings=document.querySelector('#typing-settings');
document.querySelector('#composer').hidden=false;document.querySelector('#conv-name').textContent='Synthetic conversation';document.querySelector('#to-name').textContent='Bob';document.querySelector('#send-label').textContent='Send to Bob';document.body.classList.add('show-conv');
window.ui=mountTyping({api:provider,input,line,settings});await ui.setScope({peer:'fixture/bob',thread:'a'.repeat(32)});document.querySelector('#composer').onsubmit=e=>{e.preventDefault();ui.stop();};window.ready=true;`;
const nbBootstrap=`import {mount,unmount} from '/entry.mjs';
window.calls=[];window.prefs={send:true,show:true};window.entries=[{address:'fixture/bob',label:'Bob',expires:new Date(Date.now()+5000).toISOString()}];
window.fire=null;const id='a'.repeat(32);window.host={api:async(path,body)=>{calls.push({path,body});if(path==='/api/overview')return {me:{address:'fixture/alice'},threads:[{id,peer:'fixture/bob',last:'Hello'}]};if(path.startsWith('/api/thread'))return {peer:'fixture/bob',messages:[{id,dir:'in',from:'fixture/bob',body:'Hello',kind:'message'}]};if(path.startsWith('/api/typing')){if(body){if(path.endsWith('preferences'))prefs=body;return body;}return {current:true,supported:true,preferences:prefs,entries};}throw Error('unexpected '+path)},listen:fn=>{fire=fn;return()=>{}},onOpen(){}};await mount(document.querySelector('#root'),host);window.leave=()=>unmount(document.querySelector('#root'));window.ready=true;`;
const server=http.createServer((req,res)=>{if(req.method!=='GET'){res.writeHead(405).end();return}const p=new URL(req.url,'http://fixture').pathname;let data,type='text/javascript';
if(p==='/'){type='text/html';data='<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><link rel="stylesheet" href="/assets/app.css">'+markup+'<script type="module" src="/fixture.mjs"></script>';}
else if(p==='/notebook'){type='text/html';data='<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><link rel="stylesheet" href="/style.css"><div id="root"></div><script type="module" src="/notebook.mjs"></script>';}
else if(p==='/fixture.mjs')data=bootstrap;else if(p==='/notebook.mjs')data=nbBootstrap;
else if(['/assets/typing.mjs','/assets/app.css'].includes(p)){data=fs.readFileSync(path.join(base,path.basename(p)));if(p.endsWith('css'))type='text/css';}
else if(['/entry.mjs','/style.css'].includes(p)){data=fs.readFileSync(path.join(notebook,path.basename(p)));if(p.endsWith('css'))type='text/css';}
else{res.writeHead(404).end();return}res.setHeader('Content-Type',type+'; charset=utf-8');res.end(data)});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;let browser;
try{browser=await chromium.launch({headless:true,executablePath:process.env.AGENTNET_CHROMIUM||'/usr/bin/chromium'});
for(const width of [390,1280]){const context=await browser.newContext({viewport:{width,height:900}}),page=await context.newPage(),errors=[];await context.route('**/*',r=>r.request().url().startsWith(origin+'/')?r.continue():r.abort());page.on('pageerror',e=>errors.push(e.message));
await page.goto(origin);await page.waitForFunction(()=>window.ready);
await page.evaluate(()=>{document.querySelector('#body').value='restored';document.querySelector('#body').dispatchEvent(new Event('input'))});assert.equal(await page.evaluate(()=>calls.filter(x=>x.body).length),0,'synthetic input sends nothing');
await page.locator('#body').fill('Human input');await page.waitForFunction(()=>calls.some(x=>x.body?.active===true));await page.locator('#body').press('End');await page.keyboard.type(' more');assert.equal(await page.evaluate(()=>calls.filter(x=>x.body?.active).length),1,'throttled');
await page.locator('#conv-name').click();await page.waitForFunction(()=>calls.some(x=>x.body?.active===false));
assert.equal(await page.evaluate(()=>calls.some(x=>x.body&&JSON.stringify(x.body).includes('Human input'))),false,'draft text absent');
await page.evaluate(async()=>{entries=[{address:'fixture/bob',label:'Bob',expires:new Date(Date.now()+1000).toISOString()}];await ui.refresh()});await page.getByText('Bob is typing…',{exact:true}).waitFor();
if(process.env.AGENTNET_SCREENSHOTS)await page.screenshot({path:path.join(process.env.AGENTNET_SCREENSHOTS,'typing-'+width+'.png')});
const reads=await page.evaluate(()=>calls.filter(x=>!x.body).length);await page.waitForFunction(()=>document.querySelector('#typing-line').hidden);assert.equal(await page.evaluate(()=>calls.filter(x=>!x.body).length),reads,'expiry never polls');
await page.evaluate(async()=>{await ui.showSettings();document.querySelector('#settings-profile').hidden=true;document.querySelector('#settings-notifications').hidden=false;document.querySelector('#settings-tab-profile').setAttribute('aria-pressed','false');document.querySelector('#settings-tab-notifications').setAttribute('aria-pressed','true');document.querySelector('#settings').showModal()});
await page.evaluate(()=>{window.saveGate=new Promise(r=>window.saveDone=r)});const pendingBefore=await page.evaluate(()=>calls.filter(x=>x.body?.active).length);await page.getByLabel('Share when I’m typing').uncheck();await page.evaluate(()=>document.querySelector('#settings').close());await page.evaluate(()=>ui.refresh());await page.locator('#body').fill('Opt-out saving');await page.evaluate(()=>new Promise(r=>setTimeout(r,30)));assert.equal(await page.evaluate(()=>calls.filter(x=>x.body?.active).length),pendingBefore,'opt-out suppresses starts before save completes');await page.evaluate(()=>{saveDone();window.saveGate=null;document.querySelector('#settings').showModal()});await page.waitForFunction(()=>prefs.send===false);if(process.env.AGENTNET_SCREENSHOTS)await page.screenshot({path:path.join(process.env.AGENTNET_SCREENSHOTS,'typing-settings-'+width+'.png')});
assert.equal(await page.evaluate(()=>document.querySelector('#settings').scrollWidth>document.querySelector('#settings').clientWidth),false,'settings contained');
await page.evaluate(()=>document.querySelector('#settings').close());const before=await page.evaluate(()=>calls.filter(x=>x.body?.active).length);await page.locator('#body').fill('No sharing');await page.evaluate(()=>new Promise(r=>setTimeout(r,30)));assert.equal(await page.evaluate(()=>calls.filter(x=>x.body?.active).length),before);
await page.evaluate(async()=>{prefs.send=true;await ui.refresh()});await page.locator('#body').fill('Back on');await page.waitForFunction(n=>calls.filter(x=>x.body?.active).length>n,before);await page.evaluate(()=>ui.setScope({conv:'b'.repeat(64)}));await page.waitForFunction(()=>calls.some(x=>x.body?.active===false&&x.body.scope.peer==='fixture/bob'));
await page.evaluate(async()=>{entries=[{address:'fixture/bob',label:'Bob',expires:new Date(Date.now()+5000).toISOString()}];await ui.refresh();ui.disconnect()});assert.equal(await page.locator('#typing-line').isHidden(),true);
await page.evaluate(async()=>{window.release=null;held=new Promise(r=>release=r);const pending=ui.refresh();ui.destroy();release();await pending});assert.equal(await page.locator('#typing-line').isHidden(),true,'late result after unmount ignored');
await page.goto(origin+'/notebook');await page.waitForFunction(()=>window.ready);await page.getByRole('button',{name:'fixture/bob — Hello'}).click();await page.getByText('Bob is typing…',{exact:true}).waitFor();await page.getByLabel('Message',{exact:true}).fill('Notebook draft');await page.waitForFunction(()=>calls.some(x=>x.body?.active));await page.evaluate(()=>fire({type:'change'}));await page.waitForFunction(()=>document.querySelector('textarea').value==='Notebook draft');
if(process.env.AGENTNET_SCREENSHOTS)await page.screenshot({path:path.join(process.env.AGENTNET_SCREENSHOTS,'typing-notebook-'+width+'.png')});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
await page.evaluate(()=>leave());await page.waitForFunction(()=>calls.some(x=>x.body?.active===false));assert.deepEqual(errors,[]);await context.close();}
console.log('typing UI PASS: trusted input, throttle, clear, TTL/no polling, settings, scope/unmount, Notebook draft, desktop/390');
}finally{if(browser)await browser.close();await new Promise(r=>server.close(r))}})().catch(e=>{console.error(e);process.exitCode=1});
